    .map(({ id }) => ({ id, weight: getAffixWeight(id) }));

  if (eligible.length === 0) return [];

  const count = rng.int(1, Math.min(maxCount, eligible.length));
  const selected = [];
  const remaining = [...eligible];

  for (let i = 0; i < count && remaining.length > 0; i++) {
